import{_t as e,it as t,n,rt as r}from"./chunks/framework.BVGGWBQY.js";var i=JSON.parse(`{"title":"Environment variables","description":"","frontmatter":{},"headers":[],"relativePath":"reference/environment.md","filePath":"reference/environment.md","lastUpdated":1788732279000}`),a={name:`reference/environment.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to “Environment variables”">​</a></h1><p>Every variable this server reads, in full. There is no configuration file.</p><p>Only <code>CARDDAV_URL</code> plus one credential pair is required; everything else has a default that is safe to leave alone.</p><h2 id="connection" tabindex="-1">Connection <a class="header-anchor" href="#connection" aria-label="Permalink to “Connection”">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>CARDDAV_URL</code></td><td>yes</td><td>—</td><td>Root of the CardDAV server, e.g. <code>https://dav.example.net</code>. An address book collection URL works too and limits the server to that one book. A query string or a fragment is refused.</td></tr><tr><td><code>CARDDAV_USERNAME</code></td><td>yes¹</td><td>—</td><td>Account name. Deleted from the process environment once read.</td></tr><tr><td><code>CARDDAV_PASSWORD</code></td><td>yes¹</td><td>—</td><td>Password, or an app-specific password. Deleted from the process environment once read.</td></tr><tr><td><code>CARDDAV_TOKEN</code></td><td>yes¹</td><td>—</td><td>Bearer token, instead of username and password. Setting both is refused at startup. Deleted from the process environment once read.</td></tr></tbody></table><p>¹ Either <code>CARDDAV_USERNAME</code> <strong>and</strong> <code>CARDDAV_PASSWORD</code>, or <code>CARDDAV_TOKEN</code>. Not both — which was meant is not knowable from here, and the wrong guess authenticates as somebody else.</p><p>Almost every CardDAV server wants the username and password. <code>CARDDAV_TOKEN</code> exists for the rare one that does not.</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to “Scope”">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>CARDDAV_ADDRESSBOOKS</code></td><td>no</td><td>every book the account can see</td><td>Comma-separated address books this server may touch, each a full URL, an absolute path, or the collection&#39;s final path segment. A <strong>display name is not accepted</strong> — it is chosen by whoever shared the book, is not unique, and changes.</td></tr><tr><td><code>CARDDAV_MAX_CONTACTS</code></td><td>no</td><td><code>100</code></td><td>Contacts a listing returns when the caller passes no <code>limit</code>. An integer from 1 to 500.</td></tr><tr><td><code>CARDDAV_READ_ONLY</code></td><td>no</td><td><code>false</code></td><td><code>true</code> registers only the read tools. They do not appear in <code>tools/list</code> at all rather than failing when called.</td></tr><tr><td><code>CARDDAV_ALLOW_TOOLS</code></td><td>no</td><td>all tools</td><td>Comma-separated tool names, a prefix with one trailing <code>*</code>, or <code>essential</code> for the curated preset. A name matching no tool stops the server at startup.</td></tr><tr><td><code>CARDDAV_DENY_TOOLS</code></td><td>no</td><td>—</td><td>Same shape, subtracted from whatever the allow list left.</td></tr></tbody></table><p>Setting <code>CARDDAV_ADDRESSBOOKS</code> to an empty string is a <strong>refusal</strong>, not an omission: whoever wrote <code>CARDDAV_ADDRESSBOOKS=</code> in a compose file meant to restrict something, and answering that by opening every book is the one wrong outcome. An entry matching two books stops the server rather than picking one.</p><h2 id="transport-security" tabindex="-1">Transport security <a class="header-anchor" href="#transport-security" aria-label="Permalink to “Transport security”">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>CARDDAV_INSECURE_TLS</code></td><td>no</td><td><code>false</code></td><td><code>true</code> accepts a self-signed certificate <strong>on the configured host only</strong>, through a scoped dispatcher. <code>NODE_TLS_REJECT_UNAUTHORIZED</code> is never set. It switches off the whole certificate check, hostname verification included — anyone on the path to that host can then present any certificate and receive the credentials — and the scoped dispatcher bypasses a global undici dispatcher (a proxy agent) the host process may have installed.</td></tr><tr><td><code>CARDDAV_ALLOW_PLAINTEXT</code></td><td>no</td><td><code>false</code></td><td><code>true</code> allows a plain <code>http://</code> URL to a host that is not loopback. Without it such a URL <strong>refuses to start</strong>, because it would send the credentials and every contact unencrypted on every request.</td></tr></tbody></table><p>A loopback URL needs neither. <code>http://127.0.0.1:5232</code>, <code>http://localhost:5232</code>, <code>http://[::1]:5232</code> and <code>http://[::ffff:127.0.0.1]:5232</code> are all recognised as local — the classification is numeric rather than a string comparison, so <code>127.example.com</code> is not.</p><h2 id="asking-a-person" tabindex="-1">Asking a person <a class="header-anchor" href="#asking-a-person" aria-label="Permalink to “Asking a person”">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>ELICITATION</code></td><td>no</td><td><code>true</code></td><td><strong>Not prefixed.</strong> <code>false</code> makes guarded tools use the two-call token instead of raising a dialog. Anything else is fatal.</td></tr></tbody></table><p><code>ELICITATION</code> is deliberately unprefixed, which means one <code>export ELICITATION=false</code> reaches every MCP server in the environment. That is its risk as well as its point, so a server started with it off prints a line saying so.</p><p>It is also the only variable here that defaults to <em>on</em>, which is why an unrecognised value stops the server instead of being ignored: failing open on a typo would leave the dialog running while the operator believed it was off.</p><p>See <a href="/guide/approval">asking a person</a>.</p><h2 id="how-booleans-are-read" tabindex="-1">How booleans are read <a class="header-anchor" href="#how-booleans-are-read" aria-label="Permalink to “How booleans are read”">​</a></h2><p>The direction decides the strictness, not the variable.</p><p>A switch that <strong>turns a protection on</strong> is read tolerantly — <code>1</code>, <code>true</code>, <code>TRUE</code>, <code>yes</code>, with surrounding whitespace ignored. That is <code>CARDDAV_READ_ONLY</code>. An <code>=== &#39;true&#39;</code> comparison would answer <code>CARDDAV_READ_ONLY=1</code> in a compose file with a server that quietly exposes every write tool, and the operator would not find out.</p><p>A switch that <strong>lifts a protection</strong> is compared against the exact string <code>true</code>. That is <code>CARDDAV_INSECURE_TLS</code> and <code>CARDDAV_ALLOW_PLAINTEXT</code>. Anything the operator did not spell exactly leaves the protection in place.</p><h2 id="what-is-not-here" tabindex="-1">What is not here <a class="header-anchor" href="#what-is-not-here" aria-label="Permalink to “What is not here”">​</a></h2><p>For completeness, because a reader may be looking for them:</p><ul><li><strong>No timezone variable.</strong> vCard has no timezones. A <code>BDAY</code> is a date, and one without a year stays without a year.</li><li><strong>No user-email variable.</strong> vCard has no attendees and no scheduling, so there is nothing this server would need to recognise you by.</li><li><strong>No cache or state directory.</strong> This server keeps no local copy of anything. The only state it holds is a five-minute memo of which address books exist, in memory, and <code>list_address_books</code> always refreshes it.</li></ul>`,25)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};